import json, hashlib, os, re
root="/Users/wahrfreiheit/OMP/hungary-socialist-mechanism-lab"
os.chdir(root)

cert=json.load(open("config/inference/hist_vnext_v1/BLOCKER_CERTIFICATE.json",encoding="utf-8"))
seeds=json.load(open("config/inference/hist_vnext_v1/failed_seeds.json",encoding="utf-8"))
rep=open("config/inference/hist_vnext_v1/REPORT.md",encoding="utf-8").read()

fails=[]
def chk(c,m):
    if not c: fails.append(m)

# --- required top-level fields
chk(cert["schema_version"]=="hist_vnext_h6a_blocker_v1","schema_version")
chk(cert["phase_id"]=="H6A","phase_id")
chk(cert["status"]=="BLOCKED","status")
chk(cert["blocking_code"]=="MISSING_INDEPENDENT_LINKAGE_ADMISSION","blocking_code")
chk(cert["identifiable_set"]==[],"identifiable_set")
chk(cert["inference_status"]=="NOT_RUN","inference_status")
d=cert["dimensions"]
chk(d["technical"]["status"]=="BLOCKED_PREREQUISITE","technical dim")
chk(d["structural"]["status"]=="NOT_RUN","structural dim")
chk(d["historical"]["status"]=="UNIDENTIFIED","historical dim")
chk(cert["repository"]["start_head"]=="c0b19dbd14b79cec79b58c7a1f77d14cc0b6aa5d","start HEAD")

# --- seeds file exact content
chk(seeds=={"status":"NOT_RUN","seeds":[],"reason":"H6A source/linkage prerequisite blocked; no simulation or inference started"},"failed_seeds exact content")

# --- every sha256/bytes in certificate must match actual files on disk
def sha(p):
    return hashlib.sha256(open(p,'rb').read()).hexdigest()

checked=0
def walk(o):
    global checked
    if isinstance(o,dict):
        p=o.get("path"); s=o.get("sha256"); b=o.get("bytes")
        if isinstance(p,str) and isinstance(s,str) and os.path.exists(p):
            checked+=1
            if sha(p)!=s: fails.append(f"HASH MISMATCH {p}: cert={s} actual={sha(p)}")
            if isinstance(b,int) and os.path.getsize(p)!=b: fails.append(f"BYTES MISMATCH {p}: cert={b} actual={os.path.getsize(p)}")
        if isinstance(p,str) and isinstance(o.get("stdout_sha256"),str) and os.path.exists(p):
            checked+=1
            if sha(p)!=o["stdout_sha256"]: fails.append(f"STDOUT HASH MISMATCH {p}")
            if isinstance(o.get("stdout_bytes"),int) and os.path.getsize(p)!=o["stdout_bytes"]: fails.append(f"STDOUT BYTES MISMATCH {p}")
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(cert)

print("file hash pairs verified:", checked)
print("failures so far:", fails)

