root="/Users/wahrfreiheit/OMP/hungary-socialist-mechanism-lab"; os.chdir(root)
cert=json.load(open("config/inference/hist_vnext_v1/BLOCKER_CERTIFICATE.json",encoding="utf-8"))
seeds=json.load(open("config/inference/hist_vnext_v1/failed_seeds.json",encoding="utf-8"))
rep=open("config/inference/hist_vnext_v1/REPORT.md",encoding="utf-8").read()
ct=json.dumps(cert,ensure_ascii=False)
fails=[]
def chk(c,m):
    if not c: fails.append(m)

for lbl in ["VERIFIED_BY_RUN","VERIFIED_BY_CODE","VERIFIED_BY_WEB","HYPOTHESIS","NOT_RUN"]:
    chk(lbl in rep, f"label {lbl}")
for bad in ["rank=0","zero_jacobian"]:
    chk(bad not in rep and bad not in ct, f"token {bad}")
need=["config/inference/hist_vnext_v1/commands.json","config/inference/hist_vnext_v1/logs/admission.attempt-1.stdout.json",
 "docs/phases/HIST_VNEXT/H4A-0/APPROVED_INPUT_SET.json","docs/phases/HIST_VNEXT/H4B-EXEC/REPORT.md",
 "docs/phases/HIST_VNEXT/H4A-1/REVIEW.md","docs/phases/HIST_VNEXT/H4C/MEASUREMENT_MANIFEST.json",
 "studies/HIST_VNEXT/M06/reviews/round-4.md","docs/upgrade_review/HIST_VNEXT/05_REVISED_IMPLEMENTATION_PLAN.md",
 "docs/upgrade_review/HIST_VNEXT/06_OMP_MINIMAX_HANDOFF.md",".omp/agents/phase-reviewer.md"]
for x in need: chk(x in rep, f"ref {x}")

def sha(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
n=0
def walk(o):
    global n
    if isinstance(o,dict):
        p=o.get("path")
        if isinstance(p,str) and os.path.exists(p) and isinstance(o.get("sha256"),str):
            n+=1
            chk(sha(p)==o["sha256"], f"HASH {p}")
            if isinstance(o.get("bytes"),int): chk(os.path.getsize(p)==o["bytes"], f"BYTES {p}")
        if isinstance(p,str) and os.path.exists(p) and isinstance(o.get("stdout_sha256"),str):
            n+=1
            chk(sha(p)==o["stdout_sha256"], f"STDOUT HASH {p}")
            if isinstance(o.get("stdout_bytes"),int): chk(os.path.getsize(p)==o["stdout_bytes"], f"STDOUT BYTES {p}")
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(cert)

# quoted lines must be verbatim at cited line numbers
def lines(p):
    return open(p,encoding="utf-8").read().split("\n")
for rc in cert["required_contract"]:
    L=lines(rc["path"])
    for q in rc["quote"]:
        chk(q in L, f"NOT VERBATIM in {rc['path']}: {q[:60]}")

chk(seeds=={"status":"NOT_RUN","seeds":[],"reason":"H6A source/linkage prerequisite blocked; no simulation or inference started"},"seeds exact")
print("hash/bytes pairs verified:", n)
print("FAILS:", fails)

