import json, hashlib, os, re
root="/Users/wahrfreiheit/OMP/hungary-socialist-mechanism-lab"; os.chdir(root)
cert=json.load(open("config/inference/hist_vnext_v1/BLOCKER_CERTIFICATE.json",encoding="utf-8"))
seeds=json.load(open("config/inference/hist_vnext_v1/failed_seeds.json",encoding="utf-8"))
rep=open("config/inference/hist_vnext_v1/REPORT.md",encoding="utf-8").read()
ct=json.dumps(cert,ensure_ascii=False)
fails=[]
def chk(c,m):
    if not c: fails.append(m)

# --- certificate quotes must be verbatim lines of the cited file
def lines(p): return open(p,encoding="utf-8").read().split("\n")
for rc in cert["required_contract"]:
    L=lines(rc["path"])
    for q in rc["quote"]:
        chk(q in L, f"NOT VERBATIM {rc['path']}: {q[:50]}")

# --- REPORT fenced code blocks quoting contracts must be verbatim too
blocks=re.findall(r"```\n(.*?)```", rep, re.S)
srcs=["docs/upgrade_review/HIST_VNEXT/05_REVISED_IMPLEMENTATION_PLAN.md",
      "docs/upgrade_review/HIST_VNEXT/06_OMP_MINIMAX_HANDOFF.md",
      "docs/upgrade_review/HIST_VNEXT/evidence/phase-contracts.json",
      "docs/upgrade_review/HIST_VNEXT/01_BASELINE_AND_VERSION_AUDIT.md",
      ".omp/agents/phase-reviewer.md"]
allL={s:set(lines(s)) for s in srcs}
rep_verbatim=0; rep_bad=[]
for b in blocks:
    bl=[x for x in b.split("\n") if x.strip()]
    if len(bl)<2: continue
    # find which source contains the first line
    for s in srcs:
        if bl[0] in allL[s]:
            for l in bl:
                if l not in allL[s]: rep_bad.append((s,l[:70]))
            rep_verbatim+=1
            break
chk(not rep_bad, f"REPORT non-verbatim lines: {rep_bad[:4]}")
print("REPORT verbatim blocks matched:", rep_verbatim)

# --- hash/bytes pairs
def sha(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
n=0
def walk(o):
    global n
    if isinstance(o,dict):
        p=o.get("path")
        if isinstance(p,str) and os.path.exists(p):
            if isinstance(o.get("sha256"),str):
                n+=1; chk(sha(p)==o["sha256"], f"HASH {p}")
                if isinstance(o.get("bytes"),int): chk(os.path.getsize(p)==o["bytes"], f"BYTES {p}")
            if isinstance(o.get("stdout_sha256"),str):
                n+=1; chk(sha(p)==o["stdout_sha256"], f"STDOUT {p}")
                if isinstance(o.get("stdout_bytes"),int): chk(os.path.getsize(p)==o["stdout_bytes"], f"STDOUT BYTES {p}")
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(cert)

# --- forbidden ledger hashes
for fp in ["config/inference/hist_vnext_v1/commands.json"]:
    h=sha(fp); chk(h not in ct and h not in rep, f"commands.json hash embedded")

# --- top-level contract fields
chk(cert["schema_version"]=="hist_vnext_h6a_blocker_v1","schema")
chk(cert["phase_id"]=="H6A","phase"); chk(cert["status"]=="BLOCKED","status")
chk(cert["blocking_code"]=="MISSING_INDEPENDENT_LINKAGE_ADMISSION","code")
chk(cert["identifiable_set"]==[] and cert["inference_status"]=="NOT_RUN","set/status")
d=cert["dimensions"]
chk([d["technical"]["status"],d["structural"]["status"],d["historical"]["status"]]==["BLOCKED_PREREQUISITE","NOT_RUN","UNIDENTIFIED"],"dims")
chk(cert["repository"]["start_head"]=="c0b19dbd14b79cec79b58c7a1f77d14cc0b6aa5d","head")
chk(seeds=={"status":"NOT_RUN","seeds":[],"reason":"H6A source/linkage prerequisite blocked; no simulation or inference started"},"seeds")

# --- p05 identity agreement
ident=json.load(open("config/calibration/p05.json",encoding="utf-8"))["identification"]
for p in cert["parameter_typing"]["parameters"]:
    chk(p["identification"]==ident[p["artifact_id"]],"ident "+p["artifact_id"])
    chk(p["historical_estimate"] is False,"hist flag "+p["artifact_id"])
    chk(p["artifact_id"] in rep,"report "+p["artifact_id"])
chk(cert["parameter_typing"]["counts"]["fixed"]==9 and cert["parameter_typing"]["counts"]["unidentified"]==6,"counts")
chk(len(cert["parameter_typing"]["parameters"])==15,"15 params")

# --- null hashes for missing source/admission/linkage
for m in cert["missing_source_admission_linkage"]:
    chk(m["path"] is None and m["sha256"] is None and m["admission_review"] is None and m["source_id"] is None, "missing row not null: "+m["item"][:40])
chk(len(cert["missing_source_admission_linkage"])>=8,"missing rows count")

# --- no fake digest/posterior/rank-zero
for bad in ["rank=0","zero_jacobian"]:
    chk(bad not in ct and bad not in rep, bad)
chk(cert["delivery"]["commit"] is None and cert["delivery"]["pushed"] is False,"commit null")
chk(cert["delivery"]["h6a_research_completed"] is False,"research not complete")

print("hash pairs verified:", n)
print("FAILS:", fails)

