cert=json.load(open("config/inference/hist_vnext_v1/BLOCKER_CERTIFICATE.json",encoding="utf-8"))
seeds=json.load(open("config/inference/hist_vnext_v1/failed_seeds.json",encoding="utf-8"))
rep=open("config/inference/hist_vnext_v1/REPORT.md",encoding="utf-8").read()
ct=json.dumps(cert,ensure_ascii=False)
fails=[]
def chk(c,m):
    if not c: fails.append(m)
def sha(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
def lines(p): return open(p,encoding="utf-8").read().split("\n")

# certificate quotes verbatim
for rc in cert["required_contract"]:
    L=lines(rc["path"])
    for q in rc["quote"]: chk(q in L, f"QUOTE {rc['path']}: {q[:45]}")

# REPORT blocks verbatim
srcs=["docs/upgrade_review/HIST_VNEXT/05_REVISED_IMPLEMENTATION_PLAN.md",
      "docs/upgrade_review/HIST_VNEXT/06_OMP_MINIMAX_HANDOFF.md",
      "docs/upgrade_review/HIST_VNEXT/evidence/phase-contracts.json",
      "docs/upgrade_review/HIST_VNEXT/01_BASELINE_AND_VERSION_AUDIT.md",
      ".omp/agents/phase-reviewer.md"]
allL={s:set(lines(s)) for s in srcs}
for b in re.findall(r"```\n(.*?)```", rep, re.S):
    bl=[x for x in b.split("\n") if x.strip()]
    if len(bl)<2: continue
    for s in srcs:
        if bl[0] in allL[s]:
            for l in bl: chk(l in allL[s], f"REPORT QUOTE {s}: {l[:45]}")
            break

# hashes/bytes
n=0
def walk(o):
    global n
    if isinstance(o,dict):
        p=o.get("path")
        if isinstance(p,str) and os.path.exists(p):
            for hk,bk in (("sha256","bytes"),("stdout_sha256","stdout_bytes")):
                if isinstance(o.get(hk),str):
                    n+=1; chk(sha(p)==o[hk], f"HASH {p}")
                    if isinstance(o.get(bk),int): chk(os.path.getsize(p)==o[bk], f"BYTES {p}")
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
walk(cert)

# forbidden hashes / tokens
chk(sha("config/inference/hist_vnext_v1/commands.json") not in ct and sha("config/inference/hist_vnext_v1/commands.json") not in rep,"commands hash")
for bad in ["rank=0","zero_jacobian"]: chk(bad not in ct and bad not in rep, bad)

# frozen contract fields
chk(cert["schema_version"]=="hist_vnext_h6a_blocker_v1" and cert["phase_id"]=="H6A" and cert["status"]=="BLOCKED","core")
chk(cert["blocking_code"]=="MISSING_INDEPENDENT_LINKAGE_ADMISSION","code")
chk(cert["identifiable_set"]==[] and cert["inference_status"]=="NOT_RUN","set")
d=cert["dimensions"]
chk([d[k]["status"] for k in ("technical","structural","historical")]==["BLOCKED_PREREQUISITE","NOT_RUN","UNIDENTIFIED"],"dims")
chk(cert["repository"]["start_head"]=="c0b19dbd14b79cec79b58c7a1f77d14cc0b6aa5d","head")
chk(seeds=={"status":"NOT_RUN","seeds":[],"reason":"H6A source/linkage prerequisite blocked; no simulation or inference started"},"seeds exact")

# p05 identity
ident=json.load(open("config/calibration/p05.json",encoding="utf-8"))["identification"]
for p in cert["parameter_typing"]["parameters"]:
    chk(p["identification"]==ident[p["artifact_id"]],"ident")
    chk(p["historical_estimate"] is False,"hist flag")
    chk(p["artifact_id"] in rep,"report id")
chk(len(cert["parameter_typing"]["parameters"])==15,"15")
chk(cert["parameter_typing"]["counts"]=={"fixed":9,"unidentified":6,"total":15},"counts")

# nulls for missing
for m in cert["missing_source_admission_linkage"]:
    chk(all(m[k] is None for k in ("path","sha256","admission_review","source_id")),"null row")

# protected files unchanged + labels
for p,h in {"BASELINE.md":"1f5b233f452468701ca2d87b3ec032be4654b070ed24e5853232c997d7d61b6f",
            "config/research_contract.json":"6f54522a4b9577fc8e75cb605b0cbfafddd62a9f6b8b474719f8996ada752c82",
            "uv.lock":"9fd79b625bed399c5231e1f51b478ebf375154132a30dd9538191156218882b9",
            "config/calibration/p05.json":"ef1371b66625ddaf78663cc1181679443d7288c084c18f54e1b206a5470bb6ae"}.items():
    chk(sha(p)==h, f"DRIFT {p}")
for lbl in ["VERIFIED_BY_RUN","VERIFIED_BY_CODE","VERIFIED_BY_WEB","HYPOTHESIS","NOT_RUN"]: chk(lbl in rep,f"label {lbl}")

print("hash/bytes pairs verified:", n)
print("FAILS:", fails if fails else "NONE")

