# --- certificate quotes must be verbatim lines of the cited file
def lines(p): return open(p,encoding="utf-8").read().split("\n")
for rc in cert["required_contract"]:
    L=lines(rc["path"])
    for q in rc["quote"]:
        chk(q in L, f"NOT VERBATIM {rc['path']}: {q[:50]}")

# --- REPORT fenced code blocks quoting contracts must be verbatim too
blocks=re.findall(r"```\n(.*?)```", rep, re.S)
srcs=["docs/upgrade_review/HIST_VNEXT/05_REVISED_IMPLEMENTATION_PLAN.md",
      "docs/upgrade_review/HIST_VNEXT/06_OMP_MINIMAX_HANDOFF.md",
