      "docs/upgrade_review/HIST_VNEXT/01_BASELINE_AND_VERSION_AUDIT.md",
      ".omp/agents/phase-reviewer.md"]
allL={s:set(lines(s)) for s in srcs}
rep_verbatim=0; rep_bad=[]
for b in blocks:
    bl=[x for x in b.split("\n") if x.strip()]
    if len(bl)<2: continue
    # find which source contains the first line
    for s in srcs:
        if bl[0] in allL[s]:
            for l in bl:
                if l not in allL[s]: rep_bad.append((s,l[:70]))
            rep_verbatim+=1
            break
chk(not rep_bad, f"REPORT non-verbatim lines: {rep_bad[:4]}")
print("REPORT verbatim blocks matched:", rep_verbatim)

# --- hash/bytes pairs
def sha(p): return hashlib.sha256(open(p,'rb').read()).hexdigest()
n=0
def walk(o):
    global n
    if isinstance(o,dict):
        p=o.get("path")
        if isinstance(p,str) and os.path.exists(p):
            if isinstance(o.get("sha256"),str):
                n+=1; chk(sha(p)==o["sha256"], f"HASH {p}")
                if isinstance(o.get("bytes"),int): chk(os.path.getsize(p)==o["bytes"], f"BYTES {p}")
            if isinstance(o.get("stdout_sha256"),str):
                n+=1; chk(sha(p)==o["stdout_sha256"], f"STDOUT {p}")
                if isinstance(o.get("stdout_bytes"),int): chk(os.path.getsize(p)==o["stdout_bytes"], f"STDOUT BYTES {p}")
        for v in o.values(): walk(v)
    elif isinstance(o,list):
        for v in o: walk(v)
